* { box-sizing: border-box; }

:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #f4f0df;
  background: #171a2b;
}

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: #171a2b;
  background-image: radial-gradient(#343951 1px, transparent 1px);
  background-size: 22px 22px;
}

button { font: inherit; }

.clock-card {
  width: min(100%, 560px);
  padding: clamp(22px, 6vw, 40px);
  border: 2px solid #454b64;
  border-radius: 20px;
  background: #22263a;
  box-shadow: 0 14px 0 #101220, 0 24px 50px #0d0f1b99;
  text-align: center;
}

.heading { margin-bottom: 28px; }
.eyebrow { margin: 0 0 8px; color: #f3b85c; font-size: .8rem; font-weight: 800; letter-spacing: .16em; }
h1 { margin: 0; font-size: clamp(1.7rem, 7vw, 2.3rem); line-height: 1.15; }
.hint { margin: 10px 0 0; color: #b9bfd2; }

.clocks { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.player {
  min-width: 0;
  min-height: 190px;
  padding: 18px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: #22263a;
  background: #f4f0df;
  border: 3px solid transparent;
  border-radius: 14px;
  cursor: pointer;
  transition: transform .12s ease, border-color .12s ease, background-color .12s ease;
}
.player.dark { color: #f4f0df; background: #454b64; }
.player:hover:not(:disabled) { transform: translateY(-3px); }
.player:active:not(:disabled) { transform: translateY(1px) scale(.99); }
.player:focus-visible, .pause-button:focus-visible { outline: 3px solid #f3b85c; outline-offset: 4px; }
.player.active { border-color: #f3b85c; box-shadow: 0 0 0 3px #f3b85c33; }
.player:disabled { cursor: default; }
.player-name { font-weight: 750; font-size: 1.05rem; }
.piece { margin-right: 5px; font-size: 1.35rem; vertical-align: -2px; }
.time { font-size: clamp(2.1rem, 9vw, 3.25rem); font-weight: 800; font-variant-numeric: tabular-nums; letter-spacing: .03em; line-height: 1; }
.clock-status { min-height: 1.25em; font-size: .9rem; font-weight: 700; opacity: .78; }
.announcement { min-height: 1.5em; margin: 24px 0 16px; color: #f3b85c; font-weight: 750; }
.announcement.flag { color: #ff8b78; }
.pause-button {
  min-width: 132px;
  padding: 12px 24px;
  color: #171a2b;
  background: #f3b85c;
  border: 0;
  border-radius: 10px;
  font-weight: 800;
  cursor: pointer;
  transition: transform .12s ease, filter .12s ease;
}
.pause-button:hover:not(:disabled) { filter: brightness(1.08); transform: translateY(-2px); }
.pause-button:active:not(:disabled) { transform: translateY(1px); }
.pause-button:disabled { opacity: .5; cursor: not-allowed; }

@media (max-width: 420px) {
  .clocks { gap: 10px; }
  .player { min-height: 168px; padding-inline: 6px; }
  .player-name { font-size: .98rem; }
}

const START_SECONDS = 5 * 60;
const clocks = { white: START_SECONDS, black: START_SECONDS };
const buttons = {
  white: document.getElementById("white-clock"),
  black: document.getElementById("black-clock")
};
const displays = {
  white: document.getElementById("white-time"),
  black: document.getElementById("black-time")
};
const statuses = {
  white: document.getElementById("white-status"),
  black: document.getElementById("black-status")
};
const announcement = document.getElementById("announcement");
const pauseButton = document.getElementById("pause-button");

let active = null;
let running = false;
let lastTick = 0;
let timerId = null;
let flagged = null;

function formatTime(seconds) {
  const whole = Math.max(0, Math.ceil(seconds));
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
}

function render() {
  for (const side of ["white", "black"]) {
    displays[side].textContent = formatTime(clocks[side]);
    const label = side === "white" ? "White" : "Black";
    buttons[side].classList.toggle("active", running && active === side);
    buttons[side].setAttribute("aria-pressed", String(running && active === side));
    buttons[side].setAttribute("aria-label", `${label} clock, ${formatTime(clocks[side])} remaining. Tap to ${running ? "switch the clock" : "start or resume"}.`);
    statuses[side].textContent = flagged === side ? "Flag!" : running && active === side ? "Running" : "Ready";
  }
  pauseButton.disabled = flagged !== null || active === null;
  pauseButton.textContent = running ? "Pause" : "Resume";
  pauseButton.setAttribute("aria-label", running ? "Pause clocks" : "Resume clocks");
}

function stopForFlag(side) {
  clocks[side] = 0;
  active = null;
  running = false;
  flagged = side;
  clearInterval(timerId);
  announcement.textContent = `${side === "white" ? "White" : "Black"} — Flag!`;
  announcement.classList.add("flag");
  render();
}

function tick() {
  if (!running || active === null) return;
  const now = performance.now();
  clocks[active] -= (now - lastTick) / 1000;
  lastTick = now;
  if (clocks[active] <= 0) stopForFlag(active);
  else render();
}

function start(side) {
  if (flagged) return;
  tick();
  if (flagged) return;
  active = side;
  running = true;
  lastTick = performance.now();
  announcement.textContent = `${side === "white" ? "White" : "Black"} to move.`;
  announcement.classList.remove("flag");
  clearInterval(timerId);
  timerId = setInterval(tick, 100);
  render();
}

buttons.white.addEventListener("click", () => start("white"));
buttons.black.addEventListener("click", () => start("black"));
pauseButton.addEventListener("click", () => {
  if (running) {
    tick();
    if (flagged) return;
    running = false;
    clearInterval(timerId);
    announcement.textContent = "Paused. Choose a side to resume.";
    render();
  } else if (active) {
    start(active);
  }
});

render();
